import styled from '@emotion/styled';

interface BrandRankingContainerProps {
  $marginBottom?: boolean;
  $isExport?: boolean;
}

export const BrandRankingContainer = styled('div', {
  shouldForwardProp: (propName) =>
    !['$marginBottom', '$isExport'].includes(propName),
})<BrandRankingContainerProps>(({ $marginBottom, $isExport }) => ({
  width: '1290px',
  display: 'grid',
  gap: '24px',
  ...($marginBottom === true && { marginBottom: '48px' }),
  ...($marginBottom === false && { marginBottom: '0px' }),
  ...($isExport && { width: '100%' }),
}));
